namespace Nucleus.Files;

public class FileSystem : IFileSystem
{
	public Dictionary<UtlSymId_t, SearchPathID> Path { get; } = [];
	private bool initialized = false;

	/// <summary>
	/// This stores some images in-code for the UI
	/// todo; a MUCH better way to do this, ie. something encoding in the application itself. I just haven't done much of that before
	/// </summary>
	/// <returns></returns>
	static MemorySearchPath MemBackedImages() {
		var mempath = new MemorySearchPath();

		using (var up32 = mempath.Open("ui/up32.png", FileAccess.Write, FileMode.Create))
			up32!.Write(Convert.FromBase64String(""));

		using (var left32 = mempath.Open("ui/left32.png", FileAccess.Write, FileMode.Create))
			left32!.Write(Convert.FromBase64String(""));

		using (var right32 = mempath.Open("ui/right32.png", FileAccess.Write, FileMode.Create))
			right32!.Write(Convert.FromBase64String(""));

		using (var down32 = mempath.Open("ui/down32.png", FileAccess.Write, FileMode.Create))
			down32!.Write(Convert.FromBase64String(""));

		return mempath;
	}

	/// <summary>Get base directory of config files.</summary>
	/// <returns>A string representing the path of the base directory.</returns>
	/// <remarks>
	/// Values on different platforms:
	///     Windows: <user>\AppData\Roaming
	///     Linux/macOS: ${XDG_CONFIG_HOME:-$HOME/.config}
	/// </remarks>
	/// <seealso href="https://jimrich.sk/environment-specialfolder-on-windows-linux-and-os-x/" /> 
	private static string GetConfigBaseDir() => Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);

	/// <summary>Get base directory of data files.</summary>
	/// <returns>A string representing the path of the base directory.</returns>
	/// <remarks>
	/// Values on different platforms:
	///     Windows: <user>\AppData\Local
	///     Linux/macOS: ${XDG_DATA_HOME:-$HOME/.local/share} 
	/// </remarks>
	/// <seealso href="https://jimrich.sk/environment-specialfolder-on-windows-linux-and-os-x/" />
	private static string GetDataBaseDir() => Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);

	/// <summary>Get base directory of cache files.</summary>
	/// <returns>A string representing the path of the base directory.</returns>
	/// <remarks>
	/// Values on different platforms:
	///     Windows: %TEMP% or %TMP% or <user>\AppData\Local\Temp
	///     Linux/macOS: ${XDG_CACHE_HOME:-$HOME/.cache}
	/// </remarks>
	/// <seealso href="https://jimrich.sk/environment-specialfolder-on-windows-linux-and-os-x/" />
	/// <seealso href="https://en.wikipedia.org/wiki/Environment_variable#Default_values" />
	/// <seealso href="https://specifications.freedesktop.org/basedir-spec/latest/#variables" />  
	private static string GetCacheBaseDir() =>
#if COMPILED_WINDOWS
		Environment.GetEnvironmentVariable("TEMP")
	?? Environment.GetEnvironmentVariable("TMP")
	?? System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Temp");
#else
		Environment.GetEnvironmentVariable("XDG_CACHE_HOME")
	?? System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".cache");
#endif

	/// <summary>Get base directory of state files.</summary>
	/// <returns>A string representing the path of the base directory.</returns>
	/// <remarks>
	/// Values on different platforms:
	///     Windows: Same to <see cref="GetCacheBaseDir" />
	///     Linux/macOS: ${XDG_STATE_HOME:-$HOME/.local/state}
	/// As Windows does not have similar concept, we use cache directory here instead.
	/// </remarks>
	/// <seealso href="https://jimrich.sk/environment-specialfolder-on-windows-linux-and-os-x/" />
	/// <seealso href="https://specifications.freedesktop.org/basedir-spec/latest/#variables" />
	private static string GetStateBaseDir() =>
#if COMPILED_WINDOWS
		GetCacheBaseDir();
#else
		Environment.GetEnvironmentVariable("XDG_STATE_HOME")
	?? System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), ".local", "state");
#endif

	private DiskSearchPath AddBaseGameSearchPaths() {
		return AddSearchPath<DiskSearchPath>("game", AppContext.BaseDirectory);
	}

	private void AddConfigSearchPaths(DiskSearchPath gameDiskSearchPath, ReadOnlySpan<char> gameName) {
		// This acts as the primary config search path (mounted at the head of the filesystem),
		AddSearchPath("cfg", DiskSearchPath.Combine(new DiskSearchPath(GetConfigBaseDir()), gameName));

		// XDG base directory support
		// XDG_CONFIG_DIRS sets a set of extra base directories which each one needs to be searched like ${XDG_CONFIG_HOME:-$HOME/.config}.
		// As DiskSearchPath will try creating that directory, we only add it when actually exists.
#if !COMPILED_WINDOWS
		string xdgConfigDirs = Environment.GetEnvironmentVariable("XDG_CONFIG_DIRS") ?? "/etc/xdg";
		foreach (string path in xdgConfigDirs.Split(':'))
			if (Directory.Exists(System.IO.Path.Combine(path, gameName.ToString())))
				AddSearchPath("cfg", DiskSearchPath.Combine(new DiskSearchPath(path), gameName));
#endif
		// For older Nucleus application installs; if game/cfg exists, we'll mount it at the tail.
		// New cfg writes will happen to the new folders at the head
		var cfgLegacy = DiskSearchPath.Combine(gameDiskSearchPath, "cfg");
		if (cfgLegacy.Exists())
			AddSearchPath("cfg", cfgLegacy);
	}

	private void AddAppDataSearchPaths(ReadOnlySpan<char> gameName) {
		// This is where we store persist data, game will not work correctly without them.
		AddSearchPath("appdata", DiskSearchPath.Combine(new DiskSearchPath(GetDataBaseDir()), gameName));
		// XDG base directory support
		// XDG_DATA_DIRS sets a set of extra base directories which each one needs to be searched like ${XDG_DATA_HOME:-$HOME/.local/share}.
		// As DiskSearchPath will try creating that directory, we only add it when actually exists.
#if !COMPILED_WINDOWS
		string xdgDataDirs = Environment.GetEnvironmentVariable("XDG_DATA_DIRS") ?? "/usr/local/share:/usr/share";
		foreach (string path in xdgDataDirs.Split(':'))
			if (Directory.Exists(System.IO.Path.Combine(path, gameName.ToString())))
				AddSearchPath("appdata", DiskSearchPath.Combine(new DiskSearchPath(path), gameName));
#endif
	}

	private void AddAppCacheSearchPaths(ReadOnlySpan<char> gameName) {
		// This is where we store cache data, game can generate them again if needed.
		AddSearchPath("appcache", DiskSearchPath.Combine(new DiskSearchPath(GetCacheBaseDir()), gameName));
	}

	private void AddAppStateSearchPaths(ReadOnlySpan<char> gameName) {
		// This is where we store persistent data that isn't important `appdata`, like history, logs, etc.
		AddSearchPath("appstate", DiskSearchPath.Combine(new DiskSearchPath(GetStateBaseDir()), gameName));
	}

	private void AddUserAssets(DiskSearchPath gameDiskSearchPath) {
		var assets = AddSearchPath("assets", DiskSearchPath.Combine(gameDiskSearchPath, "assets"));
		{
			AddSearchPath("audio", DiskSearchPath.Combine(assets, "audio"));
			AddSearchPath("fonts", DiskSearchPath.Combine(assets, "fonts"));
			AddSearchPath("images", MemBackedImages());
			AddSearchPath("images", DiskSearchPath.Combine(assets, "images"));
			AddSearchPath("models", DiskSearchPath.Combine(assets, "models"));
			AddSearchPath("shaders", DiskSearchPath.Combine(assets, "shaders"));
		}
	}

	public void Initialize(ReadOnlySpan<char> gameName) {
		if (initialized)
			return;

		var gameDiskSearchPath = AddBaseGameSearchPaths();
		AddConfigSearchPaths(gameDiskSearchPath, gameName);
		AddAppDataSearchPaths(gameName);
		AddAppCacheSearchPaths(gameName);
		AddAppStateSearchPaths(gameName);
		AddUserAssets(gameDiskSearchPath);

		initialized = true;
	}

	/// <summary>
	/// Gets, or creates, a <see cref="SearchPathID"/>
	/// </summary>
	/// <param name="pathID"></param>
	/// <returns></returns>
	public SearchPathID GetSearchPathID(ReadOnlySpan<char> pathID) {
		if (Path.TryGetValue(pathID.Hash(), out var pathIDObj))
			return pathIDObj;

		pathIDObj = new();
		Path[pathID.Hash()] = pathIDObj;

		return pathIDObj;
	}

	IEnumerable<SearchPath> IFileSystem.GetSearchPathID(ReadOnlySpan<char> pathID) => GetSearchPathID(pathID);

	public T AddSearchPath<T>(ReadOnlySpan<char> pathID, T searchPath, SearchPathAdd add = SearchPathAdd.ToTail) where T : SearchPath {
		var pathIDObj = GetSearchPathID(pathID);
		switch (add) {
			case SearchPathAdd.ToHead:
				pathIDObj.Insert(0, searchPath);
				break;
			case SearchPathAdd.ToTail:
				pathIDObj.Add(searchPath);
				break;
		}
		return searchPath;
	}

	public T AddSearchPath<T>(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, SearchPathAdd add = SearchPathAdd.ToTail) where T : SearchPath {
		T ret;
		switch (typeof(T).Name) {
			case nameof(DiskSearchPath):
				ret = (T)(object)new DiskSearchPath(path);
				break;
			default: throw new NotImplementedException($"Unknown FileSystem type '{typeof(T).Name}'. Please implement it in Nucleus.Core.FileSystem.");
		}

		AddSearchPath(pathID, ret, add);
		return ret;
	}


	readonly struct TemporarySearchPathInfo
	{
		public readonly SearchPath searchPath;
		public readonly string pathID;

		public TemporarySearchPathInfo(SearchPath searchPath, string pathID) {
			this.searchPath = searchPath;
			this.pathID = pathID;
		}
	}
	readonly List<TemporarySearchPathInfo> temporarySearchPaths = [];

	/// <summary>
	/// Adds a search path that is destroyed when the level is deinitialized.
	/// </summary>
	/// <typeparam name="T"></typeparam>
	/// <param name="pathID"></param>
	/// <param name="path"></param>
	/// <param name="add"></param>
	/// <returns></returns>
	public T AddTemporarySearchPath<T>(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, SearchPathAdd add = SearchPathAdd.ToTail) where T : SearchPath {
		var pathObj = AddSearchPath<T>(pathID, path, add);
		temporarySearchPaths.Add(new(pathObj, new string(pathID)));
		return pathObj;
	}

	public T AddTemporarySearchPath<T>(ReadOnlySpan<char> pathID, T path, SearchPathAdd add = SearchPathAdd.ToTail) where T : SearchPath {
		var pathObj = AddSearchPath(pathID, path, add);
		temporarySearchPaths.Add(new(pathObj, new string(pathID)));
		return pathObj;
	}

	public void RemoveTemporarySearchPaths() {
		foreach (var temp in temporarySearchPaths)
			RemoveSearchPath(temp.pathID, temp.searchPath);
	}

	public bool RemoveSearchPath(ReadOnlySpan<char> pathID, SearchPath path) {
		if (!Path.TryGetValue(pathID.Hash(), out var pathIDObj)) return false;
		return pathIDObj.Remove(path);
	}

	public bool RemoveSearchPath(ReadOnlySpan<char> pathID) {
		if (!Path.TryGetValue(pathID.Hash(), out var pathIDObj)) return false;
		return pathIDObj.RemoveAll(x => true) > 0;
	}

	public SearchPath? FindSearchPath(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path) {
		foreach (var pathIDObj in GetSearchPathID(pathID))
			if (pathIDObj.Exists(path))
				return pathIDObj;

		return null;
	}

	// Fixes annoying complaints about ref types crossing yield boundaries
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	IEnumerable<string> findFiles(string pathID, string searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		foreach (var pathIDObj in GetSearchPathID(pathID))
			foreach (var file in pathIDObj.FindFiles("", searchPattern, searchOptions))
				yield return file;
	}
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	IEnumerable<string> findDirectories(string pathID, string searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		foreach (var pathIDObj in GetSearchPathID(pathID))
			foreach (var file in pathIDObj.FindDirectories("", searchPattern, searchOptions))
				yield return file;
	}
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	IEnumerable<string> findFiles(string pathID, string path, string searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		foreach (var pathIDObj in GetSearchPathID(pathID))
			foreach (var file in pathIDObj.FindFiles(path, searchPattern, searchOptions))
				yield return file;
	}
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	IEnumerable<string> findDirectories(string pathID, string path, string searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		foreach (var pathIDObj in GetSearchPathID(pathID))
			foreach (var file in pathIDObj.FindDirectories(path, searchPattern, searchOptions))
				yield return file;
	}

	//=========================================================================================================================================================//
	//=========================================================================================================================================================//
	//=========================================================================================================================================================//
	//=========================================================================================================================================================//
	//=========================================================================================================================================================//

	public IEnumerable<string> FindFiles(ReadOnlySpan<char> pathID, ReadOnlySpan<char> searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		return findFiles(new(pathID), new(searchPattern), searchOptions);
	}

	public IEnumerable<string> FindDirectories(ReadOnlySpan<char> pathID, ReadOnlySpan<char> searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		return findDirectories(new(pathID), new(searchPattern), searchOptions);
	}

	public IEnumerable<string> FindFiles(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, ReadOnlySpan<char> searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		return findFiles(new(pathID), new(searchPattern), new(searchPattern), searchOptions);
	}

	public IEnumerable<string> FindDirectories(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, ReadOnlySpan<char> searchPattern, SearchOption searchOptions = SearchOption.TopDirectoryOnly) {
		return findDirectories(new(pathID), new(searchPattern), new(searchPattern), searchOptions);
	}

	public bool CanOpen(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, FileAccess access = FileAccess.ReadWrite, FileMode mode = FileMode.OpenOrCreate) {
		foreach (var pathObj in GetSearchPathID(pathID)) {
			if (pathObj.CheckFile(path, access, mode))
				return true;
		}

		return false;
	}

	public Stream? Open(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, FileAccess access = FileAccess.ReadWrite, FileMode mode = FileMode.OpenOrCreate) {
		foreach (var pathObj in GetSearchPathID(pathID)) {
			if (pathObj.CheckFile(path, access, mode)) {
				var stream = pathObj.Open(path, access, mode);
				if (stream != null) return stream;
			}
		}

		return null;
	}

	public bool Exists(string pathID, string path) {
		foreach (var pathObj in GetSearchPathID(pathID))
			if (pathObj.Exists(path))
				return true;

		return false;
	}

	public string? ReadAllText(string pathID, string path) {
		foreach (var pathObj in GetSearchPathID(pathID)) {
			var text = pathObj.ReadText(path);
			if (text != null) return text;
		}

		return null;
	}

	public byte[]? ReadAllBytes(string pathID, string path) {
		foreach (var pathObj in GetSearchPathID(pathID)) {
			var bytes = pathObj.ReadBytes(path);
			if (bytes != null) return bytes;
		}

		return null;
	}

	public bool ReadAllText(string pathID, string path, [NotNullWhen(true)] out string? text) {
		text = ReadAllText(pathID, path);
		return text != null;
	}

	public bool ReadAllBytes(string pathID, string path, [NotNullWhen(true)] out byte[]? bytes) {
		bytes = ReadAllBytes(pathID, path);
		return bytes != null;
	}

	public bool WriteAllText(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, ReadOnlySpan<char> text, Encoding encoding) {
		foreach (var pathObj in GetSearchPathID(pathID)) {
			var succeeded = pathObj.WriteText(path, text, encoding);
			if (succeeded) return true;
		}

		return false;
	}

	public bool WriteAllText(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, ReadOnlySpan<char> text) {
		foreach (var pathObj in GetSearchPathID(pathID)) {
			var succeeded = pathObj.WriteText(path, text);
			if (succeeded) return true;
		}

		return false;
	}

	public bool WriteAllBytes(ReadOnlySpan<char> pathID, ReadOnlySpan<char> path, byte[] data) {
		foreach (var pathObj in GetSearchPathID(pathID)) {
			var succeeded = pathObj.WriteBytes(path, data);
			if (succeeded) return true;
		}

		return false;
	}
}
